function loadSavedRoute(){try{let r=JSON.parse(localStorage.getItem(ROUTE_KEY)||'null');if(r&&typeof r.center==='string'&&typeof r.sub==='string')return r}catch(e){}return{center:'operations',sub:'live'}}
function persistRoute(){try{localStorage.setItem(ROUTE_KEY,JSON.stringify({center:route.center,sub:route.sub,toolId:route.toolId||''}))}catch(e){}}
let state=load();let route=loadSavedRoute(), mode='view', toolEditorMode='view', draft=null, selected=null, dirty=false, meetingDraft=null, dailyContext='weekday', returnRoute=null, liveIndex=0, livePaused=false, snapshotIndex=0, snapshotPaused=false;
let screenshotRestore=null, presentationRestore=null, presentationActive=false, presentationOriginRoute=null, presentationExiting=false;
function saveState(msg='CHANGES SAVED'){try{state.version=VERSION;state.audit.unshift({at:nowISO(),message:msg});localStorage.setItem(KEY,JSON.stringify(state));dirty=false;toast('✓ SAVED SUCCESSFULLY · '+msg);return true}catch(err){toast('✕ SAVE FAILED · '+err.message);return false}}
function toast(t){let e=document.querySelector('#toast');e.textContent=t;e.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>e.classList.remove('show'),2400)}
function applyRules(t){if(t.toolStatus==='Packing'&&['Not Created','Completed'].includes(t.shipping.scheduleStatus))t.shipping.scheduleStatus='Active - In Progress';if(t.toolStatus==='Shipped')t.shipping.scheduleStatus='Completed';if(['OPI','OI','FI','Powered Down'].includes(t.toolStatus)&&t.shipping.scheduleStatus==='Completed')t.shipping.scheduleStatus=t.shipping.scheduleSent?'Published':'Not Created'}
function allRules(){state.tools.forEach(applyRules)}
function activeTools(){return state.tools.filter(t=>t.toolStatus!=='Archived'&&(t.quarter||state.quarter)===state.quarter)}
function workloadTools(){return activeTools().filter(t=>t.toolStatus!=='Shipped')}
function morningSortGroup(t){let c=String(t.codename||'').trim().toLowerCase();return c==='regera'?1:c==='celestiq'?2:0}
function morningSortTools(list){return [...list].sort((a,b)=>{let g=morningSortGroup(a)-morningSortGroup(b);if(g)return g;return String(a.id||'').localeCompare(String(b.id||''),undefined,{numeric:true,sensitivity:'base'})})}
function nonArchivedTools(){return state.tools.filter(t=>t.toolStatus!=='Archived')}
function activeQuarters(){let q=[...new Set(nonArchivedTools().map(t=>t.quarter||state.quarter).filter(Boolean))];if(!q.includes(state.quarter))q.push(state.quarter);return q.sort()}
function toolViewQuarter(){return state.config?.toolViewQuarter||state.quarter}
function toolsForQuarter(q=toolViewQuarter()){return nonArchivedTools().filter(t=>(t.quarter||state.quarter)===q)}
function checklistIndex(t,code){return routeFor(t).findIndex(x=>x[0]===code)}
function fiProgress(t){if(!t.currentChecklist)return 0;if(t.currentChecklist===FI200)return 100;let r=routeFor(t),i=checklistIndex(t,t.currentChecklist);return i<0?0:Math.round(i/(r.length-1)*100)}
function microProgress(t){let r=routeFor(t),i=checklistIndex(t,t.microSchedule);return i<0?0:Math.round(i/(r.length-1)*100)}
function performance(t){let d=fiProgress(t)-microProgress(t);return d>5?['AHEAD','purple','ahead']:d<-5?['BEHIND','red','behind']:['ON SCHEDULE','green','on']}
function requiresMST(t){return ['regera','celestiq'].includes(String(t.codename||'').toLowerCase())}
function shippingKeys(t){return requiresMST(t)?[['subsystems','Subsystems'],['accessories','Accessories'],['cables','Cables'],['mat','MST Installation'],['is','IS']]:[['subsystems','Subsystems'],['accessories','Accessories'],['cables','Cables'],['is','IS']]}
function shippingProgress(t){if(t.toolStatus==='Shipped')return 100;if(t.toolStatus!=='Packing')return 0;let c=t.shipping?.completed||{},steps=shippingKeys(t).map(x=>x[0]),done=steps.filter(k=>!!c[k]).length;return Math.round(done/steps.length*100)}
function shippingStep(t){if(t.toolStatus==='Shipped')return 'Complete';if(['OPI','OI'].includes(t.toolStatus))return 'Waiting for FI';if(t.toolStatus==='FI')return 'FI Testing';if(t.toolStatus==='Powered Down')return 'Start Packing';let c=t.shipping?.completed||{};for(let [k,label] of shippingKeys(t))if(!c[k])return label;return t.toolStatus==='Packing'?'Final Packing':'FI Testing'}
function shippingLabel(t){if(t.toolStatus==='Shipped')return{label:'SHIPPED',css:'shipped'};if(t.toolStatus==='Packing')return{label:'PACKING ACTIVE',css:'active'};if(t.toolStatus==='Powered Down')return{label:'POWERED DOWN',css:'testing'};if(['OPI','OI'].includes(t.toolStatus))return{label:'WAITING FI',css:'waiting'};return{label:'IN FI',css:'testing'}}
function toolTone(t,pf){if(t.toolStatus==='Shipped')return 'shipped';if(t.toolStatus==='Packing')return 'packing';if(t.toolStatus==='Powered Down')return 'infi';if(['OPI','OI'].includes(t.toolStatus))return 'waiting';if(t.ncs.some(n=>n.state==='Escalated'&&n.blocking))return 'critical';if(pf==='BEHIND')return 'behind';if(pf==='AHEAD')return 'ahead';return 'infi'}
function cardProgress(name,p,color,step){return `<div class="card-progress"><label><span>${name}</span><b>${p}%</b></label><div class="track"><div class="fill ${color}" style="width:${p}%"></div></div><small class="card-step">${esc(step)}</small></div>`}
function quarterChoices(){let m=String(state.quarter).match(/^CY(\d{2})Q([1-4])$/);if(!m)return[state.quarter];let y=Number(m[1]),q=Number(m[2]),arr=[];for(let d=-2;d<=2;d++){let nq=q+d,ny=y;while(nq<1){nq+=4;ny--}while(nq>4){nq-=4;ny++}arr.push(`CY${String(ny).padStart(2,'0')}Q${nq}`)}return[...new Set(arr)]}
function dailyOrderedTools(){return morningSortTools(workloadTools())}
function escAge(n){if(n.state!=='Escalated')return'';let d=n.opened?Math.max(1,Math.floor((new Date(today())-new Date(n.opened.slice(0,10)))/86400000)+1):(Number(n.days)||1);return `DAY ${d}`}
function displayNcId(id){let m=String(id||'').match(/(\d+)/);return m?`NC #${m[1]}`:'NC #—'}
function shipToggle(t,k,label){let on=!!(t.shipping?.completed||{})[k],enabled=t.toolStatus==='Packing';return `<button type="button" class="ship-toggle ${on?'done':''}" data-daily-ship="${esc(k)}" data-tool-id="${esc(t.id)}" ${enabled?'':'disabled'}>${label} ${on?'✓':'○'}</button>`}
function dailyLeadProgress(t){let p=leadProgress(t);return `<div class="daily-progress-readonly"><div class="daily-progress-label"><span>Lead / Admin Progress</span><b>${p}% AUTOMATIC</b></div><div class="track"><div class="fill purple" style="width:${p}%"></div></div><small>Calculated automatically from the Current Lead / Admin Task · detailed checklist remains a visual aid</small></div>`}
function dailyReadonly(label,value){return `<div class="field daily-readonly"><label>${label}</label><div class="readonly-value">${esc(value||'—')}</div></div>`}
function dailySelect(label,f,html,cls=''){return `<label class="field ${cls}">${label}<select data-f="${esc(f)}">${html}</select></label>`}
function dailyInput(label,f,value,type='text',cls=''){return `<label class="field ${cls}">${label}<input data-f="${esc(f)}" type="${type}" value="${esc(value??'')}"></label>`}
function dailyTextarea(label,f,value,cls=''){return `<label class="field ${cls}">${label}<textarea data-f="${esc(f)}">${esc(value||'')}</textarea></label>`}
function dailyEditorTitle(){if(returnRoute?.center==='status')return `UPDATE ${returnRoute.sub==='weekend'?'WEEKEND':'WEEKDAY'} MORNING STATUS`;return 'UPDATE COMMAND CENTER'}
function dailyNcRows(t){let rows=Array.isArray(t.ncs)?t.ncs:[];if(!rows.length)return `<div class="nc-empty">No NCs / escalations recorded.</div>`;return rows.map((n,i)=>`<div class="nc-edit-row" data-daily-nc="${i}" data-opened="${esc(n.opened||today())}"><div class="nc-edit-order">${i+1}</div><label>NC #<input data-dnf="id" value="${esc(String(n.id||'').replace(/^NC\s*#?\s*/i,''))}" placeholder="73"></label><label class="nc-desc">Description<input data-dnf="description" value="${esc(n.description||'')}" placeholder="NC description"></label><label>Status<select data-dnf="state">${selectOptions(['Open','Escalated','Closed'],n.state||'Open')}</select></label><label>Days<input data-dnf="days" type="number" min="0" value="${Number(n.days)||0}"></label><label>Owner<input data-dnf="owner" value="${esc(n.owner||'')}"></label><label class="nc-poa">POA<input data-dnf="poa" value="${esc(n.poa||'')}" placeholder="Approved POA / next action"></label><button class="btn danger" type="button" data-daily-remove-nc="${i}" data-tool-id="${esc(t.id)}">REMOVE</button></div>`).join('')}
function dailyCard(t,i,total){return `<article class="daily-card daily-card-v561" data-daily="${esc(t.id)}"><div class="daily-order auto-order"><b>${i+1}</b><small>AUTO</small></div><div class="daily-editor-body"><div class="panel-head daily-tool-head"><h2>${esc(t.id)} — ${esc(t.codename).toUpperCase()}</h2><span class="state-chip ${['OPI','OI'].includes(t.toolStatus)?'waiting':t.toolStatus==='FI'?'infi':t.toolStatus.toLowerCase().replace(/\s+/g,'-')}">${esc(t.toolStatus)}</span></div>
<div class="subsection daily-section"><h3>Tool Information / Plan</h3><div class="form-grid">${dailyReadonly('UTID / Serial',t.id)}${dailyInput('Alias','alias',t.alias||'')}${dailySelect('Code Name','codename',toolTypeOptions(t.codename))}${dailySelect('Model','model',modelOptions(t,t.model))}${dailySelect('Tool Status','toolStatus',selectOptions(STATUS.filter(x=>x!=='Archived'),t.toolStatus))}${dailyReadonly('Original Quarter',t.originalQuarter||t.quarter)}${dailySelect('Current Quarter','quarter',selectOptions(quarterChoices(),t.quarter))}${dailyInput('Sales Order','salesOrder',t.salesOrder||'')}${dailyInput('Customer','customer',t.customer)}${dailySelect('Cleanroom','cleanroom',selectOptions(['CR1','CR2','CR3'],t.cleanroom))}${dailyInput('Cleanroom Bay','bay',t.bay)}${dailyInput('Tool Assignment','driver',t.driver)}${dailyInput('MFG Ship Date','shipDate',t.shipDate,'date')}${dailyInput('FI Handoff Date','fiHandoffDate',t.fiHandoffDate||'','date')}${dailyInput('Engineering Handoff Date','engineeringHandoffDate',t.engineeringHandoffDate||'','date')}${dailyInput('Engineering Return to FI','engineeringReturnDate',t.engineeringReturnDate||'','date')}${dailySelect('Forecast Target Checklist','nextForecastChecklist',`<option value="">Select Target Checklist</option>${routeOptions(t,t.nextForecastChecklist)}`)}${dailyReadonly('Calculated Forecast Date',fmtDate(forecastNextDate(t))||'TBD')}${dailyInput('SW Version','sw',t.sw)}${dailyInput('Lamp Hours','lamp',Number(t.lamp)||0,'number')}${dailySelect('Lamp State','lampState',selectOptions(['ON','OFF','TBD'],t.lampState||'ON'))}<label class="field reduced-process-field"><span>Special FI Process</span><span class="checkbox-line"><input type="checkbox" data-f="reducedProcess" ${t.reducedProcess?'checked':''}> REDUCED PROCESS</span></label></div></div>
<div class="subsection daily-section"><h3>Key Process / Test Status</h3><div class="form-grid">${dailySelect('Ironman','keyTests.ironman',selectOptions(['Not Run','Passed','Failed'],t.keyTests.ironman))}${dailySelect('AV Data','keyTests.avData',selectOptions(['Not Run','Running','Completed','Approved'],t.keyTests.avData))}${dailySelect('SCC Cleanup','keyTests.sccCleanup',selectOptions(['Not Started','In Progress','Completed'],t.keyTests.sccCleanup))}${dailySelect('Backup','keyTests.backup',selectOptions(['Not Started','In Progress','Completed'],t.keyTests.backup))}</div></div>
<div class="subsection daily-section"><h3>FI Testing / Micro Schedule</h3><div class="form-grid">${dailySelect('Current FI Checklist','currentChecklist',routeOptions(t,t.currentChecklist),'span2')}${dailySelect('Micro Schedule Target','microSchedule',routeOptions(t,t.microSchedule),'span2')}${dailySelect('Current Lead / Admin Task','currentLeadTask',`<option value="">Not Set</option>${selectOptions(LEAD_TASKS,t.currentLeadTask)}`,'span2')}<div class="field span2 micro-date-pair"><label>Micro Schedule Dates</label><div class="micro-date-grid">${dailyInput('Micro Schedule Start','microStart',t.microStart||'','date')}${dailyInput('Micro Schedule Complete','microComplete',t.microComplete||'','date')}</div></div><details class="field span4 daily-detail-workspace"><summary>Complete FI / Lead-Admin Checklist Working Aids</summary><div class="checklist-workspace"><div class="checklist-panel fi-editor"><div class="panel-head"><label>Complete FI Checklist Status</label><b>VISUAL WORKING AID</b></div>${fiChecklistRows(t)}</div><div class="checklist-panel lead-editor"><div class="panel-head"><label>Complete Lead / Admin Checklist</label><b>VISUAL WORKING AID</b></div>${leadTaskRows(t)}</div></div></details>${dailyTextarea('Latest Status','latestStatus',t.latestStatus,'span4')}${dailyTextarea('Notes','notes',t.notes||'','span4')}</div></div>
<div class="subsection daily-section"><h3>Customer Source</h3><div class="form-grid">${dailySelect('Customer Source Required','sourceRequired',selectOptions(['TBD','No','Yes'],t.sourceRequired))}${dailySelect('Customer Source Status','sourceStatus',selectOptions(['Not Started','Scheduled','Pre Source In Progress','Ready for Source','Handed to CA for Source','Source Completed','CA Handed Back to FI'],t.sourceStatus))}${dailyInput('CA Handoff / Source Start','sourceStart',t.sourceStart||t.sourceHandoff||'','date')}${dailyInput('Source Complete / System Back to FI','sourceComplete',t.sourceComplete||'','date')}</div></div>
<div class="subsection daily-section"><h3>STR</h3><div class="form-grid">${dailySelect('STR Required','strRequired',selectOptions(['TBD','No','Yes'],t.strRequired))}${dailySelect('STR Status','strStatus',selectOptions(['Not Started','In Progress','Submitted to CA for Approval','Completed - CA Approved'],t.strStatus))}${dailyTextarea('STR Notes','strNotes',t.strNotes||'','span4')}</div></div>
<div class="subsection daily-section"><h3>Shipping / Packing</h3><div class="form-grid">${dailySelect('Shipping Schedule Status','shipping.scheduleStatus',selectOptions(['Not Created','Created','Published','Active - In Progress','Updated','Completed'],t.shipping.scheduleStatus))}${dailySelect('Schedule Sent','shipping.scheduleSent',selectOptions(['No','Yes'],t.shipping.scheduleSent?'Yes':'No'))}<div class="field span4"><label>Packing / Shipping Milestones</label><div class="shipping-milestone-editor daily-milestones">${shippingKeys(t).map(([k,l])=>milestoneEditor(t,k,l)).join('')}</div></div>${dailyTextarea('Shipping Notes','shipping.notes',t.shipping.notes||'','span4')}</div></div>
<div class="subsection daily-section"><div class="panel-head"><h3>NC / ESCALATIONS / POA</h3><button class="btn" type="button" data-daily-add-nc="${esc(t.id)}">+ ADD NC</button></div><div class="daily-nc-list">${dailyNcRows(t)}</div></div>
</div></article>`}


function defaultFamilyImageName(f){if(f==='Zephyr')return 'tool-zephyr.png';return ['Regera','Celestiq'].includes(f)?'tool-regera-celestiq.png':'tool-29xx-family.png'}
function familyImage(t){let f=t.codename||t.family||'Panamera';return state.config?.toolPhotos?.[f]||('assets/'+defaultFamilyImageName(f))}
function setTheme(){let themeCenter=route.center==='update'?'operations':route.center;let [name,color,rgb]=THEMES[themeCenter]||THEMES.operations;document.body.dataset.center=themeCenter;document.documentElement.style.setProperty('--accent',color);document.documentElement.style.setProperty('--accent-rgb',rgb);let title=`${name} — ${state.quarter}`;if(route.center==='update'&&route.sub==='tool'){if(route.toolId==='new')title=`ADD TOOL — ${state.quarter}`;else{let t=(draft&&String(draft.id)===String(route.toolId))?draft:state.tools.find(x=>x.id===route.toolId);title=`${route.toolId}${t?.codename?` — ${String(t.codename).toUpperCase()}`:''} — ${state.quarter}`}}document.querySelector('#pageTitle').textContent=title;document.title=`B7 FI Command Center V${VERSION}`;document.querySelector('#versionLabel').textContent=`B7 FI COMMAND CENTER V${VERSION} · BUILD ${BUILD}`}
function nav(){let navCenter=route.center==='update'?'operations':route.center;document.querySelector('#mainNav').innerHTML=MAIN.map(x=>`<button class="${navCenter===x[0]?'active':''}" data-center="${x[0]}">${x[1]}</button>`).join('')+`<button class="global-presentation-nav" data-global-presentation title="Present Live Operations">PRESENTATION MODE</button>`;let ss=SUB[navCenter]||[],html='';if(navCenter==='operations'){let m=/CY(\d{2})Q([1-4])/.exec(state.quarter),wanted=[];if(m){let y=Number(m[1]),q=Number(m[2]);let prevQ=q-1,prevY=y;if(prevQ===0){prevQ=4;prevY--}let nextQ=q+1,nextY=y;if(nextQ===5){nextQ=1;nextY++}wanted=[`CY${String(prevY).padStart(2,'0')}Q${prevQ}`,state.quarter,`CY${String(nextY).padStart(2,'0')}Q${nextQ}`]}else wanted=[state.quarter];html=`<button class="${route.center==='operations'&&route.sub==='live'?'active':''}" data-sub="live">LIVE OPERATIONS</button>`+wanted.map(q=>`<button class="quarter-nav ${route.center==='operations'&&route.sub==='tools'&&toolViewQuarter()===q?'active':''} ${q===state.quarter?'current-quarter':''}" data-tool-quarter="${esc(q)}">${esc(q)}${q===state.quarter?' · ACTIVE':''}</button>`).join('')+`<button class="${route.center==='operations'&&route.sub==='archive'?'active':''}" data-sub="archive">TOOL ARCHIVE</button>`}else{html=ss.map(x=>`<button class="${route.sub===x[0]?'active':''}" data-sub="${x[0]}">${x[1]}</button>`).join('')}document.querySelector('#subnav').innerHTML=html+(navCenter==='operations'?'':`<span class="env-chip">DATA: ${esc(state.environment)}</span>`)}
function openIssueCount(){return state.actions.filter(a=>a.status!=='Complete').length+state.tools.reduce((n,t)=>n+t.ncs.filter(x=>x.state==='Escalated').length,0)}
function statusBars(){let escal=[];state.tools.forEach(t=>t.ncs.filter(n=>n.state==='Escalated').forEach(n=>escal.push({t,n})));let lead=escal[0];let behind=activeTools().find(t=>t.toolStatus==='FI'&&performance(t)[0]==='BEHIND');let leadMsg=lead?`TOOL ${lead.t.id} — ${displayNcId(lead.n.id)} — ${lead.n.description}${lead.n.poa?' — POA ACTIVE':''}`:'NO CRITICAL LEAD ALERTS';let sysMsg=behind?`TOOL ${behind.id} — ${checklistLabel(behind,behind.currentChecklist)} — BEHIND MICRO SCHEDULE`:`${activeTools().length} ACTIVE TOOLS — SYSTEM NORMAL`;let issueCount=openIssueCount();document.querySelector('#statusStack').innerHTML=`<div class="status-bar ${lead?'critical':'normal'}"><div class="status-left"><span class="status-dot"></span><div class="status-label"><strong>LEADS ALERT</strong><small>${lead?'CRITICAL':'NORMAL'}</small></div></div><div class="status-message ${lead?'clickable-status':''}" ${lead?`data-alert-tool="${esc(lead.t.id)}" role="button" tabindex="0" title="Open tool ${esc(lead.t.id)}"`:''}>${esc(leadMsg)}</div><button class="status-right status-open-button" data-open-issues type="button">← OPEN ${issueCount}</button></div><div class="status-bar ${behind?'attention':'normal'}"><div class="status-left"><span class="status-dot"></span><div class="status-label"><strong>SYSTEM STATUS</strong><small>${behind?'ATTENTION':'INFORMATION'}</small></div></div><div class="status-message ${behind?'clickable-status':''}" ${behind?`data-alert-tool="${esc(behind.id)}" role="button" tabindex="0" title="Open tool ${esc(behind.id)}"`:''}>${esc(sysMsg)}</div><button class="status-right status-open-button" data-open-issues type="button">← OPEN ${issueCount}</button></div>`}
function actionsFor(){let a=[];const shot=['SCREENSHOT','shot'];if(mode==='edit'){let saveLabel=(route.center==='update'&&route.sub==='tool')?'SAVE CHANGES':'SAVE CHANGES';if(route.center==='update'&&route.sub==='daily'&&returnRoute?.center==='status')saveLabel='SAVE MORNING STATUS';else if(route.center==='update'&&route.sub==='daily'&&returnRoute?.center==='operations')saveLabel='SAVE DAILY STATUS';a.push(['CANCEL','cancel'],[saveLabel,'save','save']);if(route.center==='update'&&route.sub==='tool'&&selected)a.push(['ARCHIVE TOOL','archiveTool','danger'],['DELETE TOOL','deleteTool','danger']);a.push(shot);return a}if(mode==='create'){a.push(['CANCEL','cancel'],[route.center==='update'?'SAVE TOOL':'CREATE','save','save'],shot);return a}if(mode==='morningMeeting'){a.push(['CANCEL','cancel'],['SAVE MEETING','save','save'],['COMPLETE MEETING','completeMorning','primary'],shot);return a}if(mode==='meeting'){a.push(['CANCEL','cancel'],['SAVE MEETING','save','save'],['END MEETING','endMeeting','primary'],shot);return a}
 if(route.center==='operations'){if(route.sub==='live')a.push(['UPDATE COMMAND CENTER','editDaily','primary'],['ADD TOOL','addTool','primary'],shot);else if(route.sub==='tools')a.push(['UPDATE COMMAND CENTER','editDaily','primary'],['ADD TOOL','addTool','primary'],shot);else if(route.sub==='archive')a.push(['ADD TOOL TO ARCHIVE','archiveAdd','primary'],shot);else if(route.sub==='daily')a.push(['EDIT UPDATE','edit','primary'],shot)}
 else if(route.center==='update'){if(route.sub==='tools')a.push(['ADD TOOL','addTool','primary']);if(route.sub==='daily')a.push(['EDIT DAILY UPDATE','edit','primary']);a.push(shot)}
 else if(route.center==='shipping'){a.push(['EDIT SHIPPING','edit','primary'],shot)}
 else if(route.center==='priority'){a.push(['EDIT PRIORITIES','edit','primary'],shot)}
 else if(route.center==='status'){if(route.sub==='weekday'||route.sub==='weekend'){let mt=route.sub==='weekend'?'Weekend Morning Meeting':'Weekday Morning Meeting';a.push(['UPDATE MORNING STATUS','edit','primary'],[findMorningDraft(mt)?'RESUME MORNING MEETING':'START MORNING MEETING','startMorning','primary'])}a.push(shot)}
 else if(route.center==='meeting'){a.push(['START MEETING','startMeeting','primary'],shot)}
 else if(route.center==='action'){a.push(['ADD ACTION','createAction','primary'],shot)}
 else if(route.center==='reference'){a.push(['ADD REFERENCE','createReference','primary'],shot)}
 else if(route.center==='archive'){a.push(['ADD TOOL TO ARCHIVE','archiveAdd','primary'],shot)}
 else a.push(shot);return a}
function renderActions(){let host=document.querySelector('#pageActions');let normal=actionsFor().map(x=>{let core=x[1]==='addTool'?` onclick="event.stopPropagation();window.B7Core.addTool();return false"`:x[1]==='save'&&route.center==='update'&&route.sub==='tool'?` onclick="event.stopPropagation();window.B7Core.saveTool();return false"`:x[1]==='cancel'&&route.center==='update'&&route.sub==='tool'?` onclick="event.stopPropagation();window.B7Core.cancelTool();return false"`:'';return `<button data-act="${x[1]}" class="${x[2]||''}"${core}>${x[0]}</button>`}).join('');if(route.center==='operations'&&route.sub==='live'&&mode==='view'){let n=nonArchivedTools().length||0;host.innerHTML=`<div class="ops-action-controls"><div class="ops-control-group"><button class="ops-mini-btn" data-snapshot="prev" title="Previous status page">◀</button><span>${snapshotIndex+1} / 6</span><button class="ops-pause-btn ops-stacked-toggle" data-snapshot="pause"><span>STATUS</span><strong>${snapshotPaused?'PLAY':'PAUSE'}</strong></button><button class="ops-mini-btn" data-snapshot="next" title="Next status page">▶</button></div><div class="ops-control-group"><button class="ops-mini-btn" data-carousel="prev" ${n?'':'disabled'} title="Previous tool">◀</button><span>${n?liveIndex+1:0} / ${n}</span><button class="ops-pause-btn ops-stacked-toggle" data-carousel="pause" ${n?'':'disabled'}><span>TOOLS</span><strong>${livePaused?'PLAY':'PAUSE'}</strong></button><button class="ops-mini-btn" data-carousel="next" ${n?'':'disabled'} title="Next tool">▶</button></div></div><div class="ops-action-right">${normal}</div>`;return}host.innerHTML=normal}
function syncStickyShellHeight(){if(document.body.classList.contains('screenshot-mode')||document.body.classList.contains('presentation-mode')){document.documentElement.style.setProperty('--sticky-shell-height','0px');return}let sh=document.querySelector('#stickyShell');if(sh)document.documentElement.style.setProperty('--sticky-shell-height',Math.ceil(sh.getBoundingClientRect().height)+'px')}
function shell(){setTheme();nav();statusBars();renderActions()}
function render(){allRules();shell();let titleMode=document.body.classList.contains('screenshot-mode')||document.body.classList.contains('presentation-mode');let title=titleMode?`<div id="screenshotReportTitle" class="screenshot-report-title">${esc(screenshotReportTitle())}</div>`:'';document.querySelector('#app').innerHTML=title+(VIEWS[route.center]||VIEWS.operations)();bindInputs();bindCoreInteractions();persistRoute();requestAnimationFrame(syncStickyShellHeight);if(document.body.classList.contains('presentation-mode'))requestAnimationFrame(()=>requestAnimationFrame(fitPresentation))}
