    let normalFrame=document.querySelector('.app-frame');
    if(normalFrame){normalFrame.style.zoom='';normalFrame.style.removeProperty('zoom')}
    document.documentElement.style.removeProperty('--presentation-scale');
    syncStickyShellHeight();
