function exitPresentation(){
  if(presentationExiting)return;
  presentationExiting=true;
  if(document.fullscreenElement&&document.exitFullscreen){
    try{
      let result=document.exitFullscreen();
      if(result&&typeof result.catch==='function')result.catch(()=>requestAnimationFrame(()=>requestAnimationFrame(finalizePresentationExit)));
      return;
    }catch(e){}
  }
  requestAnimationFrame(()=>requestAnimationFrame(finalizePresentationExit));
}
